  registerOnChange(function_: () => void): void {
    this.onChangeFn = function_;
  }

  registerOnTouched(function_: () => void): void {
    this.onTouchedFn = function_;
  }

  onSlChange(): void {
    const { checked } = this.el.nativeElement;
    this.onChangeFn(checked);
    this.onTouchedFn();
