import { Directive, effect, inject, signal } from '@angular/core';
import { NgControl } from '@angular/forms';

@Directive({
  selector: '[appLowercase]',
  host: {
    '(input)': 'onInput()',
  },
})
export class LowercaseDirective {
  private readonly ngControl = inject(NgControl);
  private readonly value = signal('');

  constructor() {
    effect(() => {
      const { control } = this.ngControl;
      if (control && this.value()) {
        control.setValue(this.value(), { emitEvent: false });
      }
    });
  }

  onInput() {
    const { control } = this.ngControl;
    if (control) {
      const updatedValue = (control.value ?? '').toString().toLowerCase();
      this.value.set(updatedValue);
    }
  }
}

import { Directive, ElementRef, inject } from '@angular/core';

@Directive({
  selector: '[appSlInputIconFocus]',
  host: {
    '(mouseover)': 'onMouseOver()',
    '(mouseout)': 'onMouseOut()',
    '(focus)': 'onFocus()',
    '(blur)': 'onBlur()',
  },
})
export class SlInputIconFocusDirective {
  private readonly el = inject(ElementRef);

  private isFocused = false;

  onMouseOver() {
    this.el.nativeElement.querySelector('sl-icon').style.color = 'var(--primary-contrast)';
  }

  onMouseOut() {
    if (!this.isFocused) {
      this.el.nativeElement.querySelector('sl-icon').style.color = 'var(--quaternary-contrast)';
    }
  }

  onFocus() {
    this.isFocused = true;
    this.el.nativeElement.querySelector('sl-icon').style.color = 'var(--primary-contrast)';
  }

  onBlur() {
    this.isFocused = false;
    this.el.nativeElement.querySelector('sl-icon').style.color = 'var(--quaternary-contrast)';
  }
}

import { Directive, ElementRef, inject } from '@angular/core';

@Directive({
