$pokedex-white: #fff;
$pokedex-text-dark: #032d28;

:host {
  .pokedex__container {
    position: relative;

    &.closed {
      .pokedex__flap-container {
        transform: rotateX(180deg) translate(0, -14px);
      }

      .pokedex__joystick-container {
        left: -100px;
      }

      .pokedex__pad-container::before {
        background: $pokedex-black;
      }
