      position: absolute;
      width: 100%;
      height: 100%;
      transform: rotateX(360deg);
      transform-origin: 0 100%;
      transform-style: preserve-3d;
      transition: transform 1s;

      figure {
        position: absolute;
        display: block;
        width: 100%;
        height: 100%;
        margin: 0;
        backface-visibility: hidden;
      }

