      position: relative;
      z-index: 11;
      width: 230px;
      height: 150px;
      margin-left: 70px;
      cursor: pointer;
      perspective: 800px;
    }

    .pokedex__separator {
      position: relative;
      z-index: 10;
      width: 230px;
      height: 10px;
      margin-left: 70px;
      border-bottom-width: 0;
    }

    .pokedex__bottom-part-container {
      position: relative;
      z-index: 10;
      display: flex;
      flex-direction: row;
      width: 300px;
      height: 150px;
