  }

  .pokedex__pad-container {
    width: 66px;
    background: $pokedex-dark-gray;
    border-right: var(--spacing-sm) solid $pokedex-black;
    border-top-left-radius: 75px;
    border-bottom-left-radius: 75px;

    &::before {
      position: absolute;
      width: 12px;
      height: 6px;
      margin-top: 70px;
      content: ' ';
      background: $pokedex-green;
      border: var(--spacing-xs) solid $pokedex-black;
      border-left-width: 0;
    }

    .pokedex__pad {
      position: absolute;
      width: 85px;
      height: 85px;
      margin-top: 30px;
      margin-left: 17px;
      background: $pokedex-light-gray;
      border: var(--spacing-xs) solid $pokedex-black;
      border-right-width: 0;
      border-top-left-radius: 41px;
      border-bottom-left-radius: 41px;

      &::before,
      &::after {
        position: absolute;
        width: 50px;
        height: 15px;
        margin-top: 35px;
        margin-left: var(--spacing-xxl);
        content: ' ';
        background: $pokedex-dark-gray;
      }

      &::after {
        transform: rotate(90deg);
      }
    }

    .pokedex__pad-circle {
      position: absolute;
      width: 65px;
      height: 65px;
      margin-top: 40px;
      margin-left: 30px;
      border: var(--spacing-xs) solid $pokedex-light-gray;
      border-radius: 50%;
    }
  }
}

